mapper.select:
SELECT
*
FROM bz_order${tableFix}
WHERE order_sn = #{orderSn}
LIMIT 1

SELECT
*
FROM bz_order${tableFix}
WHERE store_id = #{storeId}
  AND create_time >= #{startTime}
  AND create_time < #{endTime}
  AND order_state NOT IN (0, 10, 70, 100)
ORDER BY create_time ASC

SELECT a.order_sn,a.order_state, a.pay_sn, a.payment_code,a.order_type,a.create_time,a.pick_up_num, a.open_id,
a.activity_discount_amount,a.order_amount,a.balance_amount,a.pay_amount,a.refund_amount,a.store_id,a.store_name,
a.order_from,a.order_id, a.store_phone, a.appointment_time,a.user_coupon_id,a.order_remark,a.take_away_tel,
a.receiver_mobile,a.delivery_phone,a.delivery_name,
a.errand_reward_amount,a.errand_store_subsidy_amount
FROM bz_order a
WHERE 1=1

    AND a.store_id = #{record.storeId}


    AND a.store_id in
    
        #{storeId}
    


    
        AND a.order_state != 0 and a.order_state != 10 and a.order_state != 100
        AND NOT (a.order_type = 3 AND a.order_state = 110)
    
    
        AND (a.order_state = #{record.orderState}
            OR (a.order_type = 3 AND a.order_state = 120))
    
    
        
            AND a.order_state = #{record.orderState}
        
    


    AND NOT (a.order_type = 3 AND a.order_state IN (10, 110))


    AND a.member_id = #{record.memberId}


    AND a.open_id = #{record.openId}


    AND a.express_number like CONCAT('%',#{record.expressNumber},'%')


    AND a.payment_code = #{record.paymentCode}


    AND a.order_from = #{record.orderFrom}


    AND a.order_sn like concat('%', #{record.orderSn}, '%')


    AND a.create_time BETWEEN #{record.createTime[0]} AND #{record.createTime[1]}


    AND a.order_type = #{record.orderPcType}


    AND a.order_type IN (0, 1, 3)


    AND a.order_type = 2

ORDER BY a.create_time DESC


    SELECT a.order_sn,a.order_state, a.pay_sn, a.payment_code,a.order_type,a.create_time,a.pick_up_num,
    a.activity_discount_amount,a.order_amount,a.balance_amount,a.pay_amount,a.refund_amount,a.store_id,a.store_name,
    a.order_from,c.order_remark,a.order_id, a.store_phone, a.appointment_time,a.user_coupon_id
    FROM bz_order${tableFix} a
    LEFT JOIN bz_order_extend${tableFix} c ON a.order_sn = c.order_sn AND a.store_id = c.store_id
