            AND (a.order_state = #{record.orderState}
                OR (a.order_type = 3 AND a.order_state = 120))
        
        
            
                AND a.order_state = #{record.orderState}
            
        
    
    
        AND (a.order_state = 10 or a.order_state = 50 or a.order_state = 40 or a.order_state = 100 or
        a.order_state = 200 or a.order_state = 80)
    
    
        AND a.member_id = #{record.memberId}
    
    
        AND b.record.goods_name like CONCAT('%',#{record.goodsName},'%')
    
    
        AND a.express_number like CONCAT('%',#{record.expressNumber},'%')
    
    
        AND a.payment_code = #{record.paymentCode}
    
    
        AND a.order_from = #{record.orderFrom}
    
    
        AND a.order_sn like concat('%', #{record.orderSn}, '%')
    
    
        AND a.create_time BETWEEN #{record.beginTime} AND #{record.endTime}
    
    
        AND a.create_time >= #{record.startOrderTime}
    
    
        AND a.create_time <= #{record.endOrderTime}
    
    
        AND a.order_type = #{record.orderPcType}
    
    
        AND a.order_type IN (0, 1, 3)
    
    
