mapper.select:
select
*
from
(

    SELECT
    *
    FROM bz_order${tableFix}
    WHERE 1=1
    
        AND create_time >= #{record.startOrderTime}
    
    
        AND create_time <= #{record.endOrderTime}
    

) k order by order_id asc limit #{startIndex},#{endIndex}

mapper.update:
UPDATE bz_order
SET delivery_id = #{record.deliveryId},
    delivery_name = #{record.deliveryName},
    delivery_phone = #{record.deliveryPhone},
    order_state = #{record.orderState},
    making_time = #{record.makingTime}
WHERE order_id = #{record.orderId}
  AND order_sn = #{record.orderSn}
  AND create_time = #{record.createTime}
  AND order_type = 3
  AND order_state = #{waitingAcceptOrderState}
  AND delivery_id IS NULL

UPDATE bz_order
SET order_state = #{record.orderState}
WHERE order_id = #{record.orderId}
  AND order_sn = #{record.orderSn}
  AND create_time = #{record.createTime}
  AND order_type = 3
  AND order_state = #{waitingAcceptOrderState}
  AND delivery_id IS NULL

UPDATE bz_order

    
        order_state = #{record.orderState},
    
    
        waiting_time = #{record.waitingTime},
    
    
        finish_time = #{record.finishTime},
    
    
        errand_delivery_images = #{record.errandDeliveryImages},
    

WHERE order_id = #{record.orderId}
  AND order_sn = #{record.orderSn}
  AND create_time = #{record.createTime}
  AND order_type = 3
  AND delivery_id = #{deliveryId}
  AND order_state = #{expectedOrderState}

mapper.select:
    SELECT
        order_type orderType,
        count(*) orderNum
    FROM bz_order
    WHERE store_id = #{record.storeId}
    
        and order_sn like concat('%', #{record.orderSn}, '%')
    
    
        
            AND order_state != 0 and order_state != 10 and order_state != 100
            AND NOT (order_type = 3 AND order_state = 110)
        
        
            AND (order_state = #{record.orderState}
                OR (order_type = 3 AND order_state = 120))
        
        
            
                AND order_state = #{record.orderState}
            
        
    
    
        and order_from = #{record.orderFrom}
    
    
        AND create_time BETWEEN #{record.createTime[0]} AND #{record.createTime[1]}
    
    
        and order_type IN (0, 1, 3)
    
    
        and order_type = 2
    
GROUP BY order_type

SELECT member_id AS member_id FROM bz_order_${date} WHERE member_id != 0 AND order_state IN (40, 60, 80, 200) AND store_id IN
#{storeId}
GROUP BY member_id

SELECT
member_id AS member_id
FROM bz_order_${date}
WHERE member_id != 0
AND order_state IN (40,60,80,200)
AND DATE(create_time)  <= #{localDate}
AND store_id IN

    #{storeId}

GROUP BY member_id
